const fs=require('fs'),cp=require('child_process');
const {chromium}=require('@playwright/test');
const TARGET='assets/css/components/cards/service-card-home-feed.css';
const IMPORTER_A='assets/css/pages/home-refresh.css';
const IMPORTER_B='assets/css/pages/home/mobile/index.css';
const PAGE='index.html';
const FEED_RUNTIME='assets/js/pages/home/public-services.js';
const CARD_RUNTIME='assets/js/components/public-service-card.js';
const FIXTURE='ux051-r2-fixture.html';
const SHA=process.env.TARGET_SHA,TARGET_BLOB=process.env.TARGET_BLOB;
const A_BLOB=process.env.IMPORTER_A_BLOB,B_BLOB=process.env.IMPORTER_B_BLOB,PAGE_BLOB=process.env.PAGE_BLOB,FEED_BLOB=process.env.FEED_BLOB,CARD_BLOB=process.env.CARD_BLOB;
const VIEWPORTS=[359,419,420,421,430,559,560,561,1024];
const BODY_SEL='body.home-index-shell .featured-services .service-card--feed .service-card__body';
const TITLE_SEL='body.home-index-shell .featured-services .service-card--feed .service-card__title';
const sh=c=>cp.execSync(c,{encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim();
const assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
function guard(){assert(sh('git rev-parse HEAD')===SHA,'wrong SHA');assert(sh(`git hash-object ${TARGET}`)===TARGET_BLOB,'target blob drift');assert(sh(`git hash-object ${IMPORTER_A}`)===A_BLOB,'importer A blob drift');assert(sh(`git hash-object ${IMPORTER_B}`)===B_BLOB,'importer B blob drift');assert(sh(`git hash-object ${PAGE}`)===PAGE_BLOB,'page blob drift');assert(sh(`git hash-object ${FEED_RUNTIME}`)===FEED_BLOB,'feed blob drift');assert(sh(`git hash-object ${CARD_RUNTIME}`)===CARD_BLOB,'card blob drift');assert(sh('git status --porcelain')==='','dirty checkpoint');const p=parse(fs.readFileSync(TARGET,'utf8'));assert(p.declarations.length===108&&p.dead.length===3,`parent parse ${p.declarations.length}/${p.dead.length}`);assert(p.dead.map(d=>d.line).join(',')==='66,122,126','dead lines drift');assert(new Set(p.dead.map(d=>d.selector)).size===2,'family count drift');assert(p.dead.every(d=>d.context.includes('@media (max-width: 420px)')&&!d.important&&!d.winnerImportant),'context drift');assert(p.dead[0].winnerLine===122&&p.dead[1].winnerLine===183&&p.dead[2].winnerLine===187,'winner line drift');console.log('R2 PARENT PASS|decl=108|dead=3|families=2|changed=3|context=max420|targetBlob='+TARGET_BLOB);return p}
function writeFixture(){fs.writeFileSync(FIXTURE,`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/${IMPORTER_A}"><link rel="stylesheet" href="/${IMPORTER_B}"><style>html,body{margin:0}body{min-height:100vh}.featured-services{display:block}.service-card--feed{display:block;width:min(100%,360px);box-sizing:border-box}</style></head><body class="home-index-shell"><main><section class="featured-services"><article class="service-card--feed" data-ux051-fixture="true"><div class="service-card__body"><h3 class="service-card__title">Serviço de teste responsivo da Doke</h3><p>Conteúdo controlado para medir a cascata.</p></div></article></section></main></body></html>`) }
function removeDead(p){const src=fs.readFileSync(TARGET,'utf8'),nl=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(nl&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(`${d.property}:`),`source mismatch ${d.line}`);lines.splice(d.line-1,1)}fs.writeFileSync(TARGET,lines.join('\n')+(nl?'\n':''));const q=parse(fs.readFileSync(TARGET,'utf8')),stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(q.declarations.length===105&&q.dead.length===0,`candidate parse ${q.declarations.length}/${q.dead.length}`);assert(stat[0]==='0'&&stat[1]==='3'&&stat[2]===TARGET,`diff drift ${stat.join(' ')}`);console.log('R2 REMOVE PASS|decl=108->105|dead=3->0|families=2|additions=0|deletions=3')}
async function capture(browser,tag){const out={};let overflow=0;for(const width of VIEWPORTS){const ctx=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'}),page=await ctx.newPage();await page.route('**/*',route=>{const u=new URL(route.request().url());if(u.origin!=='http://127.0.0.1:4173')return route.abort();return route.continue()});await page.goto(`http://127.0.0.1:4173/${FIXTURE}?${tag}-${width}`,{waitUntil:'networkidle',timeout:20000});const s=await page.evaluate(({width,BODY_SEL,TITLE_SEL})=>{const card=document.querySelector('[data-ux051-fixture]'),body=document.querySelector(BODY_SEL),title=document.querySelector(TITLE_SEL);if(!card||!body||!title)throw new Error('fixture family missing');const cb=getComputedStyle(body),ct=getComputedStyle(title),cr=card.getBoundingClientRect(),br=body.getBoundingClientRect(),tr=title.getBoundingClientRect(),round=n=>Math.round(n*1000)/1000;return{width,families:[document.querySelectorAll(BODY_SEL).length,document.querySelectorAll(TITLE_SEL).length],bodyPadding:cb.padding,titleFontSize:ct.fontSize,titleLineHeight:ct.lineHeight,card:[round(cr.x),round(cr.y),round(cr.width),round(cr.height)],body:[round(br.x),round(br.y),round(br.width),round(br.height)],title:[round(tr.x),round(tr.y),round(tr.width),round(tr.height)],doc:[document.documentElement.clientWidth,document.documentElement.scrollWidth,document.body.scrollWidth]};},{width,BODY_SEL,TITLE_SEL});assert(s.families[0]===1&&s.families[1]===1,`family reach ${width}: ${s.families}`);if(s.doc[1]>s.doc[0]+1||s.doc[2]>s.doc[0]+1)overflow++;out[String(width)]=s;await ctx.close()}console.log(`R2 FIXTURE CAPTURE|tag=${tag}|viewports=${VIEWPORTS.join(',')}|samples=${VIEWPORTS.length}|families=2/2|overflowSamples=${overflow}`);return{out,overflow}}
(async()=>{assert(SHA&&TARGET_BLOB&&A_BLOB&&B_BLOB&&PAGE_BLOB&&FEED_BLOB&&CARD_BLOB,'missing env');const p=guard();writeFixture();const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{const before=await capture(browser,'before');removeDead(p);const after=await capture(browser,'after');assert(JSON.stringify(before.out)===JSON.stringify(after.out),'fixture computed/layout parity mismatch');assert(before.overflow===after.overflow,`fixture overflow parity ${before.overflow}/${after.overflow}`);console.log(`R2 FIXTURE PASS|families=2/2|viewports=${VIEWPORTS.length}|before=${VIEWPORTS.length}|after=${VIEWPORTS.length}|runtimeDiffs=0|overflowParity=${before.overflow}->${after.overflow}|boundaries=419/420/421+559/560/561|importChain=home-refresh+home/mobile/index`)}finally{await browser.close()}}finally{server.kill('SIGTERM')}sh(`git reset --hard ${SHA}`);sh('git clean -fdx');assert(sh('git rev-parse HEAD')===SHA&&sh(`git hash-object ${TARGET}`)===TARGET_BLOB&&sh('git status --porcelain')==='','restore drift');console.log(`R2 CHECKPOINT PASS|sha=${SHA}|productMutation=0|issueCreated=0|prCreated=0`)})().catch(e=>{console.error(e.stack||e);process.exit(1)});
